(r, big) => {
    const n = big ? 20000 : r.int(0, 9);
    const vals = r.distinct(n, big ? -100000 : -20, big ? 100000 : 20);
    let root = null;
    const make = v => ({ v, l: null, r: null });
    for (const v of vals) {
      if (!root) { root = make(v); continue; }
      let cur = root;
      for (;;) {
        if (v < cur.v) { if (cur.l) cur = cur.l; else { cur.l = make(v); break; } }
        else { if (cur.r) cur = cur.r; else { cur.r = make(v); break; } }
      }
    }
    const out = [], q = root ? [root] : [];
    for (let i = 0; i < q.length; i++) {
      const node = q[i];
      if (!node) { out.push(null); continue; }
      out.push(node.v);
      q.push(node.l, node.r);
    }
    while (out.length && out[out.length - 1] === null) out.pop();
    const span = big ? 100000 : 22;
    const a = r.int(-span, span), b = r.int(-span, span);
    return [out, Math.min(a, b), Math.max(a, b)];
  }

