function sumInBounds(root: TreeNode | null, low: number, high: number): number {
  let sum = 0;
  const stack: (TreeNode | null)[] = [root];
  while (stack.length) {
    const node = stack.pop();
    if (!node) continue;
    if (node.val >= low && node.val <= high) sum += node.val;
    stack.push(node.left, node.right);
  }
  return sum;
}

