class Solution:
    def sumInBounds(self, root: Optional[TreeNode], low: int, high: int) -> int:
        total, stack = 0, [root]
        while stack:
            node = stack.pop()
            if not node:
                continue
            if low <= node.val <= high:
                total += node.val
            stack.append(node.left)
            stack.append(node.right)
        return total

